<?php
$current=[];foreach($records as $record){$key=$record['values']['code']??'DEFAULT';if(!isset($current[$key]))$current[$key]=$record;}
$current=array_filter($current,fn($r)=>!in_array($r['values']['code']??'',['ARK_LOAN','ARK_ADVANCE'],true));
$isComponent=$module==='pay_component';if($isComponent)$current=array_filter($current,fn($r)=>($r['values']['category']??'')===$componentCategory);$listTitle=$isComponent?(['Earning'=>'Allowances','Deduction'=>'Deductions','Employer'=>'Employer contributions'][$componentCategory]):($module==='pay_structure'?'Salary structures':'Payslip designs');
?>
<section class="card pay-panel" data-pay-list>
<div class="pay-panel-heading"><div><h2><?=h($listTitle)?> <span class="pay-count"><?=count($current)?></span></h2><p class="pay-muted">Latest revision of each configuration. Earlier revisions remain in history.</p></div><label class="pay-search">Search<input type="search" data-pay-search placeholder="Search by name or code" aria-label="Search payroll configurations"></label></div>
<?php if($isComponent):?><div class="pay-filter-chips" aria-label="Component filters"><button class="button is-active" type="button" data-pay-method="" aria-pressed="true">All</button><button class="button" type="button" data-pay-method="Fixed" aria-pressed="false">Fixed</button><button class="button" type="button" data-pay-method="Percentage" aria-pressed="false">Percentage</button><button class="button" type="button" data-pay-method="other" aria-pressed="false">Other calculations</button></div><?php endif;?>
<div class="pay-table pay-modern-table"><table><thead><tr><th>Name / code</th><?php if($isComponent):?><th>Taxable</th><th>Calculation</th><th>Amount / rate</th><th>Based on</th><th>Prorated</th><?php elseif($module==='pay_structure'):?><th>Components</th><th>Variable pay</th><?php else:?><th>Layout</th><th>Custom attributes</th><?php endif;?><th>Effective period</th><th>Status</th><th>Actions</th></tr></thead><tbody>
<?php foreach($current as $r):$d=$r['values'];?><tr data-pay-row data-pay-calculation="<?=h($d['calculation']??'')?>" data-pay-category="<?=h($d['category']??'')?>"><td><strong><?=h($r['title'])?></strong><small><?=h($d['code']??'DEFAULT')?></small></td><?php if($isComponent):?><td><?=!empty($d['taxable'])?'Yes':'No'?></td><td><?=h($d['calculation'])?></td><td><?=h(in_array($d['calculation'],['Fixed','Percentage'],true)?(($d['value']??'0').($d['calculation']==='Percentage'?'%':'')):($d['calculation']==='Formula'?($d['formula']??''):'Calculated'))?></td><td><?=h($d['basis']??'—')?></td><td><?=!empty($d['proratable'])?'Yes':'No'?></td><?php elseif($module==='pay_structure'):?><td><?=count($d['components']??[])?> components<details><summary>View components</summary><?php foreach($d['components']??[] as $component):?><p><?=h(($component['name']??$component['code']).' · '.$component['category'])?></p><?php endforeach;?></details></td><td><?=!empty($d['variable_enabled'])?'Up to '.h((string)($d['variable_cap']??0)).'%':'Disabled'?></td><?php else:?><td><?=($d['template_mode']??'standard')==='html'?'Custom HTML':'Standard'?></td><td><?=count($d['attributes']??[])?></td><?php endif;?><td><?=h($d['effective_from'])?><small><?=h($d['effective_to']?:'No end date')?></small></td><td><span class="pay-badge <?=$r['status']==='Active'?'pay-badge-success':''?>"><?=h($r['status'])?></span></td><td><?php if(can($pdo,$user,'payroll.settings.manage')):?><a class="button" href="?page=<?=h($page)?><?=$isComponent?'&amp;category='.h($componentCategory):''?>&amp;revision=<?=$r['id']?>">Revise</a><?php else:?>View only<?php endif;?></td></tr><?php endforeach;?>
<tr data-pay-empty <?=count($current)?'hidden':''?>><td colspan="9">No matching configurations.</td></tr></tbody></table></div>
<p class="pay-muted" data-pay-result><?=count($current)?> configurations</p></section>


